        case Z_NODE_TAG_LABELVALUE:
            free(u->data);
            break;
        case Z_NODE_TAG_STRINGCHUNK:
            z_t1073_StringChunkData_destroy((z_t1073_StringChunkData_t*)u->data);
            free(u->data);
