            break;
        case Z_NODE_TAG_CALL:
            z_t1081_CallData_destroy((z_t1081_CallData_t*)u->data);
            free(u->data);
            break;
        case Z_NODE_TAG_TYPEOFEXPR:
            free(u->data);
            break;
        case Z_NODE_TAG_NAMEDOPERATION:
            free(u->data);
            break;
        case Z_NODE_TAG_DATABLOCK:
            z_t1087_DataBlockData_destroy((z_t1087_DataBlockData_t*)u->data);
            free(u->data);
            break;
        case Z_NODE_TAG_YIELDEXPR:
            free(u->data);
            break;
        case Z_NODE_TAG_STATEMENT:
            z_t1091_StatementData_destroy((z_t1091_StatementData_t*)u->data);
            free(u->data);
            break;
        case Z_NODE_TAG_STATEMENTLINE:
            free(u->data);
            break;
        case Z_NODE_TAG_ASSIGNMENT:
            z_t1095_AssignmentData_destroy((z_t1095_AssignmentData_t*)u->data);
            free(u->data);
            break;
        case Z_NODE_TAG_REASSIGNMENT:
            free(u->data);
            break;
        case Z_NODE_TAG_SWAPSTMT:
            free(u->data);
            break;
        case Z_NODE_TAG_EXPRESSION:
            free(u->data);
            break;
        case Z_NODE_TAG_IFEXPR:
            z_t1103_IfData_destroy((z_t1103_IfData_t*)u->data);
